half_token = b""
while len(data) != total_bytes:
    block = self._read_block()  # read next block
    if not block:
        if half_token:
            block = bytearray(b" ")  # flush half_token
        else:
            # eof
            break

    block = self._ignore_comments(block)

    if half_token:
        block = half_token + block  # stitch half_token to new block
        half_token = b""

